insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Lucky Seven Gold Label","rar":"shelf","f":"Lucky Seven","x":"Gold Label","p":90.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Lucky Seven Gold Label Small Batch","Lucky Seven Small Batch"],"img":"https://b3331825.assetcdn.net/3331825/wp-content/uploads/2025/09/Lucky_seven-.png","u":"https://luckysevenspirits.com/buy-now/","pr":"Lucky Seven","mk":"f183f58d-ebba-464e-8236-c76abde70d45"},{"n":"Lucky Seven The Workhorse","rar":"shelf","f":"Lucky Seven","x":"The Workhorse","p":97.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://b3331825.assetcdn.net/3331825/wp-content/uploads/2024/02/The-Workhorse-Kentucky-Straight-Bourbon-Whiskey-png--300x300.png","u":"https://luckysevenspirits.com/buy-now/","pr":"Lucky Seven","mk":"f183f58d-ebba-464e-8236-c76abde70d45"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
